net = ipaddress.ip_network('172.29.0.0/24')
targets = []
for ip in net.hosts():
    targets.append(str(ip))
print('scanning', len(targets), 'hosts')
def check(ip):
    # quick: check port 80, 8081, 8080, 8000, 5000 with 0.05 timeout via connect_ex
    results = []
    for port in [80, 8081, 8080, 8000, 5000, 443, 3000, 9000]:
        s = socket.socket()
        s.settimeout(0.05)
        try:
            if s.connect_ex((ip, port)) == 0:
                results.append(port)
        except Exception:
            pass
        finally:
            s.close()
    return ip, results
with concurrent.futures.ThreadPoolExecutor(max_workers=64) as ex:
    futs = {ex.submit(check, ip): ip for ip in targets}
    for f in concurrent.futures.as_completed(futs):
        ip, ports = f.result()
        if ports:
