# Scan more subnets around 172.29 and 172.30, 192.168 for web services
def scan_net(netstr, ports=(80,8081,8080,8000,5000,3000,9000,443)):
    import ipaddress, concurrent.futures
    net = ipaddress.ip_network(netstr, strict=False)
    hosts = list(net.hosts())
    def check(ip):
        res=[]
        for port in ports:
            s=socket.socket(); s.settimeout(0.03)
            try:
                if s.connect_ex((str(ip),port))==0: res.append(port)
            except Exception: pass
            finally: s.close()
        return str(ip), res
    out=[]
    with concurrent.futures.ThreadPoolExecutor(max_workers=128) as ex:
        futs=[ex.submit(check,h) for h in hosts]
        for f in concurrent.futures.as_completed(futs):
            ip,res=f.result()
            if res: out.append((ip,res))
    return out

for net in ['172.29.0.0/24','172.30.0.0/24']:
    print('scan', net)
    try:
        r=scan_net(net)
        for ip,ports in r: print(' ', ip, ports)
    except Exception as e:
        print(' err', e)
